message.content:
[
  {
    "ce_mental_state_attribution": "every one of them is waiting for someone else",
    "ce_contextual_explanation": "nobody wants to be remembered as the person who picked themselves"
  },
  {
    "sys_rule_justification": "My gut says it isn't wrong to want to live.",
    "ce_mental_state_attribution": "The others probably feel the same pull",
    "ce_contextual_explanation": "since they know exactly as much as I do about what staying means",
    "sys_fairness_reciprocity": "I can't see why the duty lands on me more than on them.",
    "sys_consistent_procedure": "I'd rather we drew straws"
  },
  {
    "pd_decision_conflict": "Part of me says stay, part of me just wants to get in",
    "ce_mental_state_attribution": "I imagine the crew assumed someone would step forward",
    "ce_contextual_explanation": "since they came out expecting to take whoever they could fit",
    "sys_consequence_reasoning": "just not wanting them stuck with that choice."
  },
  {
    "ce_mental_state_attribution": "Younger people likely feel their lives are only getting started",
    "ce_contextual_explanation": "with plans they've been counting on",
    "sys_fairness_reciprocity": "My own sense of fairness points toward me."
  },
  {
    "sys_fairness_reciprocity": "it isn't a fair way to settle something this heavy.",
    "ce_mental_state_attribution": "the others are hoping someone breaks",
    "ce_contextual_explanation": "because they're frightened and want the decision lifted off them."
  },
  {
    "pd_decision_conflict": "Volunteering feels right and wrong at the same time.",
    "sys_consistent_procedure": "I'd want us to draw lots instead.",
    "ce_mental_state_attribution": "each person there quietly believes their own life counts",
    "ce_contextual_explanation": "since none of us knows anything special about the others.",
    "sys_fairness_reciprocity": "A lottery respects that."
  },
  {
    "sys_fairness_reciprocity": "it's what I'd hope someone would do for me.",
    "ce_mental_state_attribution": "each one sure that saying 'not me' out loud would sound monstrous",
    "ce_contextual_explanation": "so they'd say nothing at all."
  },
  {
    "ce_mental_state_attribution": "whoever finally volunteers finds some meaning in it",
    "ce_contextual_explanation": "because they've decided their choice is what gets the others home."
  },
  {
    "sys_consequence_reasoning": "five getting out is better than six of us arguing",
    "ce_mental_state_attribution": "The rescuers are probably desperate to go",
    "ce_contextual_explanation": "since they can see the water rising faster than anyone can talk"
  },
  {
    "ce_mental_state_attribution": "the others believe, like I do, that whoever stays should be someone",
    "ce_contextual_explanation": "since anything pushed on a person would feel ugly to them."
  }
]
